-- c001-v001: Júdás Jézus Krisztus szolgája testvére pedig Jakabnak a– –ban Istenben Atyában szeretetteknek és Jézus Krisztusban megtartottaknak elhívottaknak
-- c001-v002: irgalom nektek és békesség és szeretet sokasodjon
-- c001-v003: Szeretteim minden igyekezetet téve írni nektek –ról a– közös mi üdvösségünkről szükséget kaptam írni nektek buzdítva harcolni a– egyszer átadott a– szenteknek hitért
-- c001-v004: belopóztak mert némelyek emberek akik régen előre–megírattak –ra erre a– ítéletre istentelenek a– a– Istenünk mi kegyelmét változtatók –vá kicsapongássá és az– egyetlen Urat és Urat mi Jézust Krisztust megtagadók
-- c001-v005: Emlékeztetni pedig titeket akarok tudókat titeket egyszer mindent hogy az– Úr népet –ból földjéből Egyiptomnak megmentvén a– másodszor a– nem hívőket elpusztította
-- c001-v006: angyalokat és a– nem megtartókat a– maguk kezdetét hanem elhagyókat a– saját lakhelyüket –ra ítéletre nagy napnak kötelékekben örök alatt sötétségben megtartotta
-- c001-v007: miként Szodoma és Gomorra és a– körülöttük lévő városok a– hasonló módon ezekhez paráználkodván és elmenvén után testnek másnak feküsznek–előttünk példaként tűznek örök büntetését elszenvedők
-- c001-v008: Hasonlóképpen mégis is ezek álmodozók testet ugyan beszennyeznek uraságot pedig megvetnek dicsőségeket pedig káromolnak
-- c001-v009: a– pedig Mihály az– arkangyal amikor az– ördöggel vitatkozván beszélt –ról a– Mózes testéről nem mert ítéletet hozni káromlásét hanem mondta Dorgáljon–meg téged az–Úr
-- c001-v010: ezek pedig amiket ugyan nem tudnak káromolják amiket pedig ösztönösen mint az– oktalan állatok tudnak –ban ezekben elvesznek
-- c001-v011: jaj nekik mert a– útján a– Káinnak jártak és a– tévelygésébe a– Bálámnak béréért kiöntötték–magukat és a– lázadásában a– Kórénak elvesztek
-- c001-v012: Ezek vannak akik –ban a– szeretetvendégségeitekben ti sziklazátonyok együtt–lakmározók félelem–nélkül magukat legeltetők felhők víztelen által szelektől elsodort fák őszi gyümölcstelen kétszer meghalt gyökerestől–kitépett
-- c001-v013: hullámok vad tengernek tajtékzó a– maguk szégyenüket csillagok bolygók akiknek a– homály a– sötétségé –ra örökre tartatik
-- c001-v014: Prófétált pedig is ezekről hetedik –tól Ádámtól Énók mondván Íme jött az–Úr –ban szent tízezreiben az–ő
-- c001-v015: végezni ítéletet ellen mindenkinek és meggyőzni mindenkit az– istenteleneket –ról minden a– cselekedetükről istentelenség az–ő melyekkel istentelenkedtek és –ról minden a– kemény–szavakról melyeket szóltak ellene őneki bűnösök istentelenek
-- c001-v016: Ezek vannak zúgolódók panaszkodók szerint a– kívánságaik az–ő járók és a– szájuk az–ő szól dagályos–szavakat csodálók személyeket haszonért kedvéért
-- c001-v017: Ti pedig szeretteim emlékezzetek a– igékre a– előre–mondott által az– apostolok az– Urunk mi Jézus Krisztusnak
-- c001-v018: hogy mondták nektek hogy –ban utolsó az– időben lesznek csúfolódók szerint a– maguk kívánságai járók az– istentelenségeknek
-- c001-v019: Ezek vannak akik elkülönülők érzékiek Szellemet nem bírók
-- c001-v020: ti pedig szeretteim épülvén magatokat a– legszentebb ti hitetekben –ban Szellemben Szentben imádkozván
-- c001-v021: magatokat –ban szeretetében Istennek tartsátok–meg várván az– irgalmát az– Urunknak mi Jézus Krisztusnak –ra életre örökre
-- c001-v022: és akiket ugyan könyörüljetek kételkedőkön
-- c001-v023: akiket pedig mentsétek–meg –ból tűzből kiragadván akiket pedig könyörüljetek –ban félelemben gyűlölvén is az– –tól a– testtől beszennyezett ruhát
-- c001-v024: A–nak pedig képesnek megőrizni titeket botlás–nélkül és állítani elé a– dicsőségének az–ő feddhetetlenül –ban ujjongásban
-- c001-v025: egyedül Istennek Megmentőnknek mi által Jézus Krisztus a– Urunk mi dicsőség fenség erő és hatalom előtt minden a– kornak és most és –ba minden a– korokba ámen

